package in.aicon.pocket;
import android.content.Context;import androidx.work.*;import java.util.*;import java.util.concurrent.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class SyncWorkSchedulerTest {
 Context context;WorkManager work;String a="1234567890",b="9876543210";
 @Before public void setup()throws Exception{context=RuntimeEnvironment.getApplication();try{work=WorkManager.getInstance(context);}catch(IllegalStateException e){WorkManager.initialize(context,new Configuration.Builder().setMinimumLoggingLevel(android.util.Log.ERROR).build());work=WorkManager.getInstance(context);}work.cancelAllWork().getResult().get(10,TimeUnit.SECONDS);}
 @After public void stop()throws Exception{work.cancelAllWork().getResult().get(10,TimeUnit.SECONDS);}
 @Test public void requestsUseSelectedSubjectNetworkConstraintsAndInexactThirtyMinuteCadence(){PeriodicWorkRequest periodic=SyncWorkScheduler.periodic(a);OneTimeWorkRequest edit=SyncWorkScheduler.edit(a);assertEquals(a,periodic.getWorkSpec().input.getString("subject"));assertEquals(TimeUnit.MINUTES.toMillis(30),periodic.getWorkSpec().intervalDuration);assertEquals(NetworkType.CONNECTED,periodic.getWorkSpec().constraints.getRequiredNetworkType());assertTrue(periodic.getWorkSpec().constraints.requiresBatteryNotLow());assertEquals(TimeUnit.SECONDS.toMillis(10),edit.getWorkSpec().initialDelay);assertEquals(a,edit.getWorkSpec().input.getString("subject"));}
 @Test public void repeatedEditEnqueueKeepsOnePendingJobAndLocalSelectionCancelsIt()throws Exception{OneTimeWorkRequest first=SyncWorkScheduler.edit(a),second=SyncWorkScheduler.edit(a);work.enqueueUniqueWork(SyncWorkScheduler.NOW,ExistingWorkPolicy.KEEP,first).getResult().get(10,TimeUnit.SECONDS);work.enqueueUniqueWork(SyncWorkScheduler.NOW,ExistingWorkPolicy.KEEP,second).getResult().get(10,TimeUnit.SECONDS);List<WorkInfo> requests=work.getWorkInfosForUniqueWork(SyncWorkScheduler.NOW).get(10,TimeUnit.SECONDS);assertEquals(1,requests.size());assertEquals(first.getId(),requests.get(0).getId());SyncWorkScheduler.selected(work,null,true).getResult().get(10,TimeUnit.SECONDS);assertEquals(WorkInfo.State.CANCELLED,work.getWorkInfoById(first.getId()).get(10,TimeUnit.SECONDS).getState());}
 @Test public void reopeningSameLedgerDoesNotCancelItsPendingEditJob()throws Exception{OneTimeWorkRequest first=SyncWorkScheduler.edit(a);work.enqueueUniqueWork(SyncWorkScheduler.NOW,ExistingWorkPolicy.KEEP,first).getResult().get(10,TimeUnit.SECONDS);SyncWorkScheduler.selected(work,a,false).getResult().get(10,TimeUnit.SECONDS);assertFalse(work.getWorkInfoById(first.getId()).get(10,TimeUnit.SECONDS).getState().isFinished());}
}
